 if(state.analysisMetric!=='uae-project-coverage')return;
 const note=tlQ('#analysis-note'),counts=aeUaeState.manifest?.counts||{},all=Number(counts.projects??0),quality=counts.coordinateQuality||{},source=Number(quality.projectOrSource??0),approximate=Number(quality.approximateCommunityCentre??0),unmapped=Number(quality.withoutCoordinates??0);
 const text=all.toLocaleString()+(aeUaeState.degraded?' reviewed snapshot':' catalogue')+' projects across seven emirates · '+source.toLocaleString()+' reported project/source locations · '+approximate.toLocaleString()+' approximate community locations · '+unmapped.toLocaleString()+' without coordinates'+(aeUaeState.degraded?' · live catalogue unavailable':'')+'. Colour shows catalogue density, not prices, demand or expected returns.';
