var UAE_DUBAI_STATUS_REPORT={"sourceId":"continental-dld-mashrooi-project-status-20261101","originator":"Dubai Land Department (Mashrooi project register)","republisher":"Continental Club Property LLC","title":"Dubai DLD Project Construction Database","sourcePageUrl":"https://continentalclub.ae/en/project-status/","sourceCsvUrl":"https://continentalclub.ae/data/project-status.csv","originatorPageUrl":"https://dubailand.gov.ae/en/open-data/real-estate-data/","license":"CC BY 4.0, as stated by the republisher for this dataset","attribution":"Continental Club Property, based on Dubai Land Department project registry data. Dataset \"Dubai DLD Project Construction Database\", snapshot of 1 November 2026. https://continentalclub.ae/data/project-status.csv","sourcePublicationDate":"2026-11-01","retrievedAt":"2026-11-02T19:26:12Z","evidenceClass":"licensed_secondary_copy_of_authority_project_register","grain":"one_republisher_csv_row_per_dld_project_number","rowCount":3871,"distinctProjectNumbers":3871,"distinctNames":3852,"actualCsvFieldCount":14,"sourcePageClaimedFieldCount":16,"fields":["project_number","project_name","developer_number","developer_name","community","land_number","total_area_sqm","total_units","completion_percent","completion_date","previous_percent","previous_date","start_date","handover_date"],"rawBytes":578534,"rawSha256":"3a1df52f5116bd8b14babe4cb44fa5fcdb31097e6c6e2fc366f6327f96a2be2f","independentReadbackSha256":"3a1df52f5116bd8b14babe4cb44fa5fcdb31097e6c6e2fc366f6327f96a2be2f","compressedBytes":161544,"compressedSha256":"e013090b0fc97772b3f95111068e07fe4f795439d49ec2299bada523abbb0b8b","nonEmptyByField":{"project_number":3871,"project_name":3871,"developer_number":3871,"developer_name":3871,"community":3871,"land_number":3857,"total_area_sqm":3871,"total_units":3871,"completion_percent":3871,"completion_date":2963,"previous_percent":2844,"previous_date":2844,"start_date":3871,"handover_date":3407},"geometryCaptured":false,"v48IdentityCrosswalk":"79 reviewed one-to-one links in reviewed-v48-crosswalk.json; 3,792 source IDs remain unmatched. Fifteen JVC links use DLD area-code 681 evidence. Another 29 specific identities are corroborated by Emaar South and Nshama Town Square project pages. Eight Dubai Marina and Sobha Hartland identities have project-specific developer evidence; the DLD annual report explicitly equates Marsa Dubai with Dubai Marina. Four more named developments have project-specific developer pages corroborating their marketed areas. No blanket district equivalence is inferred.","limits":"This is a dated CC BY 4.0 republished DLD register snapshot, not a live DLD API or an all-UAE census. Percentages are the last recorded technical inspection and may be stale; handover dates are declared, not actual. Sixty-seven reviewed V48 identity links do not supply geometry, sales, prices, or new project-pin coordinates, and do not revise V48 status or timelines.","normalizedBytes":1963576,"normalizedSha256":"7334b5f6db0ebdcc9731a5c9d5b2a84308f32b45ee245ed45a942b3bf16bac44","normalizedCompressedBytes":210976,"normalizedCompressedSha256":"57bf913b3477409cd39b8c60aab7a6baa8891b5d7faa0d593d361e95633ee5fc"};
