   const ajman=mapMode==='ajman-sales',mapped=ajman?areaData?.scope?.mappedReportedSales||0:areaData?.scope?.mappedSaleRecords||0,unmapped=ajman?areaData?.scope?.unmappedReportedSales||0:areaData?.scope?.unmappedSaleRecords||0,detail=(areaData?.mappedAreas||[]).find(area=>historicalKey(area)===selectedHistoricalArea);
